<!doctype html><html lang="pt-BR"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enviar fotos</title><style>*{box-sizing:border-box}body{margin:0;padding:18px;background:#172236;color:#edf3fb;font:16px system-ui}.box{max-width:520px;margin:auto;padding:22px;border:1px solid #43536c;border-radius:16px;background:#253248}.card{margin:14px 0;padding:14px;border:1px solid #4b5d78;border-radius:10px;background:#1d293d}.pick{display:block;padding:14px;border:2px dashed #7184a0;border-radius:9px;text-align:center;font-weight:700;cursor:pointer}.pick input{position:absolute;width:1px;height:1px;opacity:0}.preview{display:grid;grid-template-columns:58px 1fr auto;gap:9px;align-items:center;margin-top:10px;color:#c3cede;font-size:12px}.preview img{width:58px;height:58px;object-fit:cover;border-radius:7px}.preview button,button{border:0;border-radius:8px;padding:10px;background:#b84249;color:#fff;font-weight:800;cursor:pointer}button[type=submit]{width:100%;margin-top:14px;padding:14px}.note{padding:11px;border-radius:8px;background:#203a57;color:#cce0f4;font-size:13px}.ok{padding:14px;border:1px solid #4b9070;border-radius:9px;background:#244438;color:#c8f0d6}.progress{height:9px;overflow:hidden;border-radius:8px;background:#152033}.progress span{display:block;width:0;height:100%;background:#6bb58a;transition:width .15s}#uploadState{margin-top:12px}button:disabled{opacity:.65;cursor:wait}</style><main class="box"><h1>Comprovação fotográfica</h1><p>Envie a foto da identificação e a foto da leitura.</p>@if($mode === 'pending')<form id="photoForm" method="post" enctype="multipart/form-data" action="{{ route('reading-corrections.evidence.upload',$token) }}">@csrf
<section class="card"><strong>Foto da placa/identificação</strong><p>Placa, código ou característica legível.</p><label class="pick">Selecionar foto<input type="file" name="plate_photo" accept="image/*" capture="environment"></label><div class="preview" data-preview="plate_photo"></div></section><section class="card"><strong>Foto do hodômetro/horímetro</strong><p>Painel mostrando claramente a leitura.</p><label class="pick">Selecionar foto<input type="file" name="reading_photo" accept="image/*" capture="environment"></label><div class="preview" data-preview="reading_photo"></div></section><p id="error" class="note" hidden></p><button id="send" type="submit">Enviar fotos</button><div id="uploadState" aria-live="polite" hidden><strong>Enviando fotos... <span id="percent">0%</span></strong><div class="progress"><span id="bar"></span></div></div></form>
@elseif($mode === 'expired')<p class="note">Este link expirou. Gere outro QR Code no computador.</p>@else<div class="ok"><strong>✓ Fotos enviadas com sucesso.</strong><p>Você pode voltar ao computador e concluir a correção.</p></div>@endif</main>
@if($mode === 'pending')<script>const form=document.getElementById('photoForm'),send=document.getElementById('send'),state=document.getElementById('uploadState'),bar=document.getElementById('bar'),percent=document.getElementById('percent'),error=document.getElementById('error');let sending=false;document.querySelectorAll('input[type=file]').forEach(input=>input.addEventListener('change',()=>{const f=input.files[0],p=document.querySelector(`[data-preview="${input.name}"]`);if(!f){p.innerHTML='';return}const u=URL.createObjectURL(f);p.innerHTML=`<img src="${u}" alt="Prévia da foto"><span>${f.name}</span><button type="button" aria-label="Remover foto">X</button>`;p.querySelector('button').onclick=()=>{input.value='';p.innerHTML=''}}));form.addEventListener('submit',e=>{e.preventDefault();if(sending)return;sending=true;send.disabled=true;state.hidden=false;error.hidden=true;const data=new FormData(form),xhr=new XMLHttpRequest();xhr.open('POST',form.action);xhr.setRequestHeader('Accept','application/json');xhr.upload.onprogress=e=>{if(!e.lengthComputable)return;const n=Math.round(e.loaded/e.total*100);bar.style.width=n+'%';percent.textContent=n+'%';send.textContent=`Enviando... ${n}%`};xhr.onload=()=>{let body={};try{body=JSON.parse(xhr.responseText)}catch(_){}if(xhr.status>=200&&xhr.status<300){form.outerHTML=`<div class="ok"><strong>✓ Fotos enviadas com sucesso</strong><p>${body.message||'As imagens foram recebidas pelo CHM.'}</p><p>Você pode voltar ao computador e continuar a correção da leitura.</p></div>`;return}sending=false;send.disabled=false;send.textContent='Enviar fotos';state.hidden=true;error.textContent=Object.values(body.errors||{}).flat().join(' ')||body.message||'Não foi possível enviar as fotos. Tente novamente.';error.hidden=false};xhr.onerror=()=>{sending=false;send.disabled=false;send.textContent='Enviar fotos';state.hidden=true;error.textContent='Falha de conexão. Tente novamente.';error.hidden=false};xhr.send(data)})</script>@endif</html>
